function format(hours) {
  return `${hours.toFixed(1)}h`;
}

export function timeSheet(entries, whole) {
  const lines = [];

  for (const entry of entries) {
    lines.push(`${entry.task}: ${format(entry.hours)}`);
  }

  if (whole) {
    var format = (hours) => `${Math.round(hours)}h`;
  }

  return lines;
}
